<?php session_start();require_once "config/database.php";$error="";$flash=$_SESSION["flash"]??"";unset($_SESSION["flash"]);
if($_SERVER["REQUEST_METHOD"]==="POST"){$email=trim($_POST["email"]);$p=$_POST["password"];$s=$conn->prepare("SELECT * FROM users WHERE email=?");$s->bind_param("s",$email);$s->execute();$r=$s->get_result();if($r->num_rows===1){$u=$r->fetch_assoc();if(password_verify($p,$u["password"])){$_SESSION["user_id"]=$u["id"];$_SESSION["name"]=$u["name"];$_SESSION["role"]=$u["role"];header("Location: ".($u["role"]==="admin"?"admin/dashboard.php":"dashboard.php"));exit;}else $error="Incorrect password.";}else $error="Email not registered.";}
